//! Explicit wire versions. Never regenerate an accepted contract from current
//! catalog_scenario code, and never normalize a submitted Lua code string.
use super::{digest, json, require};
use crate::Result;
use civ6_native_bridge_rs::paid_catalog::COUNT;
use serde::Serialize;
use serde_json::Value;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
pub enum SourceContractVersion {
    Legacy4cd,
    NilAdjusted068,
    /// Generated by the checked-in 851 example: non-local AI owners only.
    NormalAi851,
}

impl SourceContractVersion {
    pub(super) const ALL: [Self; 3] = [Self::Legacy4cd, Self::NilAdjusted068, Self::NormalAi851];

    /// Receipt label and capture-key prefix.
    pub(super) fn marker(self) -> &'static str {
        match self {
            Self::Legacy4cd | Self::NilAdjusted068 => "CATALOG880",
            Self::NormalAi851 => "CATALOG_NORMAL_AI_V1",
        }
    }
    pub(super) fn artifact(self) -> &'static str {
        match self {
            Self::Legacy4cd | Self::NilAdjusted068 => "normal-catalog22.jsonl",
            Self::NormalAi851 => "normal-ai-observer-v1.jsonl",
        }
    }
    pub(super) fn prepare_receipt(self) -> &'static str {
        match self {
            Self::Legacy4cd | Self::NilAdjusted068 => "CATALOG880 official civics only; UI automatic submission paused; no game turn requested",
            Self::NormalAi851 => "CATALOG_NORMAL_AI_V1 normal observer: official AI title budgets; local human owns no subject; UI callbacks unchanged; no game turn requested",
        }
    }
    /// Frozen subject owner per source. 851 never assigns local human slot 0:
    /// source 21 wraps to slot 1, which therefore owns two persons.
    pub(super) fn owner(self, source: usize) -> usize {
        match self {
            Self::Legacy4cd | Self::NilAdjusted068 => (source + 1) % COUNT,
            Self::NormalAi851 if source == COUNT - 1 => 1,
            Self::NormalAi851 => source + 1,
        }
    }
    /// 851 runner appends the native process to every Lua receipt after start.
    pub(super) fn native_process_suffix(self) -> bool {
        self == Self::NormalAi851
    }
}

pub(super) struct Contract {
    pub version: SourceContractVersion,
    pub data: Value,
    pub sha256: &'static str,
}

impl Contract {
    pub fn load(version: SourceContractVersion) -> Result<Self> {
        let (raw, sha256) = match version {
            SourceContractVersion::Legacy4cd => (
                include_str!("../../tests/fixtures/catalog-check/source-contract.json"),
                "2ce6c4df27af3f82a9fd4f9f8d4bce52ddfba604241b4e17a1258d8d80d0f3f2",
            ),
            SourceContractVersion::NilAdjusted068 => (
                include_str!(
                    "../../tests/fixtures/catalog-check/source-contract-nil-adjusted-068.json"
                ),
                "cbebf7fe0cb633e8d541205f667762b637c4cadd3ca19e90337a9738bec67e42",
            ),
            SourceContractVersion::NormalAi851 => (
                include_str!(
                    "../../tests/fixtures/catalog-check/source-contract-normal-ai-851.json"
                ),
                "16b5dec69852d0713828273a0c009f1c66ae0cb972308279c430d25ecd2eaeea",
            ),
        };
        require(
            digest(raw) == sha256,
            "embedded source contract hash is outside the explicit allowlist",
        )?;
        Ok(Self {
            version,
            data: json(raw)?,
            sha256,
        })
    }
}
